time->format('H:i') }} </small> </div> </td> <td class="corporate-cell"> <div class="description-content"> <p class="mb-0 text-dark lh-sm expandable-text" id="descripción-{{ $section['route_prefix'] }}-{{ $item->id }}" style="altura máxima: 3em; desbordamiento: oculto; transición: altura máxima 0.3s ease;"> {{ $item->description ?? 'Sin descripción disponible' }} </p> @if(strlen($item->description ?? '') > 65) <small class="text-muted mt-1 d-block toggle-text" onclick="toggleText('description-{{ $section['route_prefix'] }}-{{ $item->id }}')"> <i class="fas fa-chevron-down me-1 toggle-icon"></i> <span class="toggle-label">Mostrar más</span> </small> @endif </div> </td> <td class="corporate-cell"> @switch($item->severity) @case('minor') <span class="severity-badge severe-low"> <div class="severity-indicator"></div> <span>Leve</span> </span> @break @case('moderado') <span class="severity-badge severe-medium"> <div class="severity-indicator"></div> <span>Moderada</span> </span> @break @case('grave') <span class="severity-badge severe-high"> <div class="severity-indicator"></div> <span>Grave</span> </span> @break@case('fatal') <span class="severity-badge severe-critical"> <div class="severity-indicator"></div> <span>Fatal</span> </span> @break @default <span class="severity-badge severe-pending"> <div class="severity-indicator"></div> <span>En revisión</span> </span> @endswitch </td> <td class="text-center corporate-cell"> <div class="response-indicator"> <span class="response-count">{{ $item->eventResponses->count() }}</span> <i class="fas fa-comment-dots ms-1 text-muted"></i> </div> </td> <td class="text-center corporate-cell"> <a href="{{ route('sstsena.' . $section['prefijo_de_ruta'] . '.respuestas.índice',$item->id) }}" class="corporate-btn"> <i class="fas fa-folder-open me-2"></i> <span>Revisar caso</span> </a> </td> </tr> @empty <tr> <td colspan="6" class="text-center py-5"> <div class="empty-state-corporate"> <div class="empty-icon mb-3"> <i class="fas {{ $section['icon'] }} fa-3x text-muted opacity-25"></i> </div> <h6 class="text-muted mb-2 fw-normal">No se encontraron registros de {{ strtolower($section['title']) }}</h6> <p class="text-muted mb-0 small"> Los nuevos incidentes se registrarán y mostrarán aquí automáticamente </p> </div> </td> </tr> @endforelse <style> /* Paleta de colores corporativa */ :root { --corporate-primary: #1a1a1a; --corporate-secondary: #f8f9fa; --corporate-accent: #6c757d; --corporate-border: #e9ecef; --corporate-shadow: rgba(0, 0, 0, 0.08); --corporate-hover: #f1f3f4; --corporate-text: #343a40; --corporate-muted: #6c757d; --corporate-success: #28a745; --corporate-warning: #ffc107; --corporate-danger: #dc3545; --corporate-info: #17a2b8; } /* Animaciones minimalistas */ @keyframes fadeIn { de { opacidad: 0; transformación: translateY(15px); } a { opacidad: 1; transformación: translateY(0); } } @keyframes fadeOut { de { opacidad: 1; transformación: translateY(0); } a { opacidad: 0; transformación: translateY(-15px); } } @keyframes slideInUp { de { opacidad:0; transform: translateY(20px); } a { opacidad: 1; transform: translateY(0); } } .fade-in { animación: fadeIn 0.4s salida fácil; } .fade-out { animación: fadeOut 0.3s entrada fácil hacia adelante; } .section-item { animación: slideInUp 0.5s salida fácil ambos; } .corporate-row { animación: slideInUp 0.3s salida fácil ambos; } /* Encabezado corporativo */ .corporate-header { background: linear-gradient(135deg, var(--corporate-primary) 0%, #2c2c2c 100%); border-radius: 12px; overflow: hidden; } .header-content { color: blanco; position: relativa; } .header-icon { color: rgba(255, 255, 255, 0.9); margin-bottom: 1rem; } /* Tarjetas corporativas */ .corporate-card { background: white; border-radius: 8px; border: 1px solid var(--corporate-border); overflow: hidden; transition: all 0.3s ease; } .corporate-card:hover { transform: translateY(-2px); box-shadow: 0 12px 24px var(--corporate-shadow); border-color: #dee2e6; } /* Encabezados de sección */ .section-header { background: var(--corporate-secondary); border-bottom: 1px solid var(--corporate-border); } .section-icon { width: 48px; height: 48px; border-radius: 8px; display: flex; align-items: center; justify-content: center; border: 1px solid rgba(0, 0, 0, 0.08); } .stats-container { text-align: center; min-width: 80px; } .stats-number { font-size: 1.75rem; font-weight: 700; color: var(--corporate-text); line-height: 1; } .stats-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--corporate-muted); font-weight: 600; } /* Tabla corporativa */ .corporate-table { font-size: 0.9rem; } .corporate-header-row { background: linear-gradient(135deg, #f8f9fa 0%, #ffffff 100%); border-bottom: 2px solid var(--corporate-border); } .corporate-th { font-weight: 600; font-size: 0.8rem; letter-spacing: 0.3px; text-transform: uppercase; color: var(--corporate-muted); padding: 1.25rem 1rem; border: none; white-space: nowrap; } .th-content { display: flex; align-items: center; gap: 0.5rem; } .corporate-cell { padding: 1.25rem 1rem; vertical-align: middle; border-bottom: 1px solid #f8f9fa; transition: background-color 0.2s ease; } .corporate-row:hover .corporate-cell { background-color: var(--corporate-hover); } /* ID de referencia */ .reference-id { font-family: 'SF Mono', 'Monaco', 'Consolas', monospace; font-size: 0.9rem; font-weight: 600; } /* Información de fecha y hora */ .datetime-info { min-width: 120px; } /* Descripción y contenido de evidencia */ .description-content p, .evidence-content p { font-size: 0.9rem; line-height: 1.4; margin-bottom: 0; } .toggle-text { cursor: pointer; transition: color 0.2s ease; } .toggle-text:hover { color: var(--corporate-primary); } .toggle-icon { transición: transformar 0.3s facilidad; } .expanded .toggle-icon { transform: rotate(180deg); } .toggle-text:hover .toggle-label { text-decoration: underline; } /* Insignias de severidad corporativas */ .severity-badge { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.875rem; border-radius: 6px; font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.3px; border: 1px solid transparent; transition: all 0.2s ease; } .severity-indicator { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; } .severity-low { background-color: #d4edda; color: #155724; color del borde: #c3e6cb; } .severidad-baja .indicador-de-severidad { color de fondo: #28a745; } .severidad-media { color de fondo: #fff3cd; color: #856404; color del borde: #ffeaa7; } .severidad-media .indicador-de-severidad { color de fondo: #ffc107; } .severidad-alta { color de fondo: #f8d7da; color: #721c24; color del borde: #f5c6cb; } .severidad-alta .indicador-de-severidad { color de fondo: #dc3545; } .severidad-crítica { color de fondo: #f5f5f5; color: #495057; color del borde: #dee2e6; } .severity-critical .severity-indicator { background-color: #343a40; } .severity-pending { background-color: #e2e3e5; color: #383d41; border-color: #d6d8db; } .severity-pending .severity-indicator { background-color: #6c757d; } /* Indicador de respuesta */ .response-indicator { display: flex; align-items: center; justify-content: center; gap: 0.25rem; } .response-count { font-weight: 700; font-size: 1.1rem; color: var(--corporate-text); } /* Botón corporativo */ .corporate-btn { display: inline-flex; align-items: center; gap: 0.5rem; relleno: 0.625rem 1.25rem; fondo: blanco; color: var(--corporate-text); borde: 1.5px sólido var(--corporate-border); radio del borde: 6px; decoración del texto: ninguna; peso de la fuente: 600; tamaño de la fuente: 0.85rem; transición: todo 0.2s facilidad; espacio en blanco: nowrap; } .corporate-btn:hover { fondo: var(--corporate-primary); color: blanco; color del borde: var(--corporate-primary); transformación: translateY(-1px); sombra del cuadro: 0 4px 8px rgba(0, 0, 0, 0.12); decoración del texto: ninguna; } /* Estado vacío corporativo */ .empty-state-corporate { relleno: 3rem 2rem; } .empty-icon { margin-bottom: 1rem; } /* Alerta corporativa */ .corporate-alert { background: linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%); border: 1px solid #c3e6cb; color: #155724; } .alert-icon { width: 36px; height: 36px; background: rgba(21, 87, 36, 0.1); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #155724; } /* Diseño responsive empresarial */ @media (max-width: 1200px) { .stats-container { display: none; } .section-content { justify-content: flex-start !importante; } } @media (ancho máximo: 992px) { .accidents-th-extra, .accidents-cell-extra { visualización: ninguna; } } @media (ancho máximo: 768px) { .header-content { relleno: 2.5rem 1rem !importante; } .header-content h1 { tamaño de fuente: 1.5rem; } .section-content { dirección flexible: columna; alinear elementos: inicio flexible !importante; espacio: 1rem; } .corporate-th { tamaño de fuente: 0.7rem; relleno: 1rem 0.75rem; } .corporate-cell { relleno: 1rem 0.75rem; } .corporate-btn { relleno: 0.5rem 1rem; font-size: 0.8rem; } } /* Mejoras de accesibilidad */ .corporate-btn:focus, .severity-badge:focus, .toggle-text:focus { outline: 2px solid #007bff; outline-offset: 2px; } /* Estilos de impresión */ @media print { .corporate-header, .corporate-btn, .toggle-text { display: none; } .expandable-text { max-height: none !important; overflow: visible !important; } .corporate-card { box-shadow: none !important; border: 1px solid #dee2e6 !important; break-inside: avoid; } .section-header { background: #f8f9fa !important; } } /* Desplazamiento suave */ html { scroll-behavior: smooth; } /* Optimización de carga */ .corporate-card { contiene: estilo de diseño; } .corporate-table { contiene: diseño; } /* Estilos para el contenedor de evidencia en la tabla */ .evidence-container { ancho máximo: 200px; } .evidence-preview { pantalla: flex; dirección flexible: columna; alinear elementos: flex-start; } .evidence-thumbnail { borde: 1px sólido #dee2e6; radio del borde: 4px; transición: all 0.3s ease; ancho máximo: 100%; } .evidence-thumbnail:hover { color del borde: var(--corporate-primary); sombra del cuadro: 0 2px 8px rgba(0, 0, 0, 0.1); } .evidence-actions { pantalla: flex; gap: 0.5rem; } .evidence-actions .btn { padding: 0.25rem 0.5rem; font-size: 0.8rem; } </style> <script> function toggleText(elementId) { const textElement = document.getElementById(elementId); const toggleElement = textElement.nextElementSibling; const isExpanded = textElement.classList.contains('expanded'); if (isExpanded) { textElement.style.maxHeight = '3em'; textElement.classList.remove('expanded'); toggleElement.querySelector('.toggle-label').textContent = 'Mostrar más'; toggleElement.quserySelector('.toggle-icon').style.transform = 'rotate(0deg)'; } else { textElement.style.maxHeight = textElement.scrollHeight + 'px'; textElement.classList.add('expanded'); toggleElement.querySelector('.toggle-label').textContent = 'Mostrar menos'; toggleElement.querySelector('.toggle-icon').style.transformar = 'rotar (180 grados)'; } } </script> @endsection